      const redrawSelection=()=>{draw();document.querySelectorAll('[data-sequence]').forEach(canvas=>drawSkeleton(canvas,pose,Number(canvas.dataset.sequence),{highlight:selectedKey}))};
      $('#profile-guided-mechanics').addEventListener('jointselectionchange',event=>{selectedKey=event.detail.key;selectedDimension=event.detail.dimension;redrawSelection()});
      clock.addEventListener('timeupdate',draw);clock.addEventListener('play',()=>$('#profile-play').textContent=`Ⅱ ${label('pauseDelivery')}`);clock.addEventListener('pause',()=>{if($('#profile-play'))$('#profile-play').textContent=`▶ ${label('playDelivery')}`});
      $('#profile-play').addEventListener('click',()=>clock.paused?clock.play():clock.pause());$('#profile-progress').addEventListener('input',e=>clock.currentTime=Number(e.target.value)/pose.fps);$('#profile-rate').addEventListener('change',e=>clock.playbackRate=Number(e.target.value));
